<script setup>import{Head}from'@inertiajs/vue3';import AdminLayout from '../../../Layouts/AdminLayout.vue';import DataPanel from '../../../Components/Ui/DataPanel.vue';import EmptyState from '../../../Components/Ui/EmptyState.vue';import PageHeader from '../../../Components/Ui/PageHeader.vue';defineOptions({layout:AdminLayout});defineProps({suppliers:{type:Array,default:()=>[]},rows:{type:Array,default:()=>[]}});</script>
<template><Head title="مقارنة أسعار الموردين"/><PageHeader title="مقارنة أسعار الموردين" icon="bi-arrows-collapse" subtitle="آخر سعر استلام موحّد لكل مكوّن؛ الأخضر الأرخص والأحمر الأغلى"/><DataPanel title="مصفوفة الأسعار" :count="rows.length" icon="bi-grid-3x3-gap-fill"><div v-if="rows.length" class="compare-wrap"><table><thead><tr><th>المكوّن</th><th>فجوة السعر</th><th v-for="supplier in suppliers" :key="supplier.id"><a :href="supplier.url">{{supplier.name}}</a></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><a :href="row.historyUrl"><strong>{{row.name}}</strong><small>/ {{row.unit}}</small></a></td><td><span v-if="row.range>.01" :class="{danger:row.range>20}">{{row.range}}%</span><small v-else>—</small></td><td v-for="price in row.prices" :key="price.supplierId" :class="{cheap:price.cheapest,pricey:price.priciest}"><b>{{price.value??'—'}}</b><small v-if="price.ago">{{price.ago}}</small></td></tr></tbody></table></div><EmptyState v-else icon="bi-table" title="لا بيانات للمقارنة" message="تظهر المقارنة بعد استلام نفس المكوّن من أكثر من مورد."/><div v-if="rows.length" class="legend"><span class="cheap">الأرخص</span><span class="pricey">الأغلى</span><span>فجوة أكبر من 20% = فرصة توفير قوية</span></div></DataPanel></template>
